'use strict';

/**
 * Certificate links are generated by cv-render.js, so neither the static
 * reference walk nor the page-load smoke test ever requests them. These browser
 * checks verify the rendered markup at both page depths and the PDF response.
 */

const { test, expect } = require('@playwright/test');
const path = require('node:path');
const { ROOT } = require('../helpers');

const CV_DATA = require(path.join(ROOT, 'js', 'cv-data.js'));
const LINKED = CV_DATA.certifications.filter((cert) => cert.link);

test('Platform Engineer CV renders linked certificate PDFs at the CV depth', async ({ page, request }) => {
  await page.goto('/portfolio/cv/platform-engineer.html');

  await expect(page.locator('body')).toHaveAttribute('data-theme', 'modern');
  await expect(page.locator('h1')).toContainText('Jade Makwela');

  const links = page.locator('.cert-info h3 a');
  await expect(links).toHaveCount(LINKED.length);

  for (const cert of LINKED) {
    const link = page.locator('.cert-info h3 a', { hasText: cert.title });
    await expect(link).toHaveCount(1);
    await expect(link).toHaveAttribute('href', `../../${cert.link}`);
    await expect(link).toHaveAttribute('target', '_blank');
    await expect(link).toHaveAttribute('rel', /noopener/);

    const response = await request.get(`/${cert.link}`);
    expect(response.status(), `${cert.link} status`).toBe(200);
    expect(response.headers()['content-type']).toMatch(/^application\/pdf\b/i);
  }
});

test('engagement CV renders certificate PDFs at the engagement depth', async ({ page, request }) => {
  await page.goto('/portfolio/cv/engagement/minimal.html');

  // The engagement format is a flat document: certificates render as list
  // links, not as the card view's .cert-info blocks.
  const links = page.locator('a[href$=".pdf"]');
  await expect(links).toHaveCount(LINKED.length);

  for (const cert of LINKED) {
    const link = page.locator('a[href$=".pdf"]', { hasText: cert.title });
    await expect(link).toHaveAttribute('href', `../../../${cert.link}`);

    const response = await request.get(`/${cert.link}`);
    expect(response.status(), `${cert.link} status`).toBe(200);
  }
});

test('unlinked certifications remain plain text on the Platform Engineer CV', async ({ page }) => {
  await page.goto('/portfolio/cv/platform-engineer.html');

  const unlinked = CV_DATA.certifications.filter((cert) => !cert.link);
  expect(unlinked.length).toBeGreaterThan(0);

  for (const cert of unlinked) {
    const heading = page.locator('.cert-info h3', { hasText: cert.title });
    await expect(heading).toHaveCount(1);
    await expect(heading.locator('a')).toHaveCount(0);
  }
});
